import React from "react";
import { alpha, useTheme } from "@mui/material/styles";
import { Box, IconButton, Stack, Tab, Tabs, Typography } from "@mui/material";
import { useDispatch, useSelector } from "react-redux";
import { CaretLeft, File, Image, LinkSimple } from "phosphor-react";
import { UpdateSidebarType } from "../../redux/slices/app";
import { extractURL } from "../../utils/urlProcess";
import { convertToIST } from "../../utils/formatTime";
import truncateString from "../../utils/truncate";
import useResponsive from "../../hooks/useResponsive";
import { rightPanelHeaderSx, rightPanelSx } from "../../theme/rightPanel";

const EmptyTab = ({ icon, title, detail }) => {
  const theme = useTheme();
  return (
    <Stack alignItems="center" justifyContent="center" spacing={1.25} sx={{ flex: 1, textAlign: "center", px: 3 }}>
      <Box sx={{ width: 52, height: 52, borderRadius: "17px", display: "grid", placeItems: "center", color: "primary.main", bgcolor: alpha(theme.palette.primary.main, 0.09) }}>{icon}</Box>
      <Typography variant="subtitle2">{title}</Typography>
      <Typography variant="caption" color="text.secondary">{detail}</Typography>
    </Stack>
  );
};

const SharedMessages = () => {
  const theme = useTheme();
  const isDesktop = useResponsive("up", "md");
  const dispatch = useDispatch();
  const [value, setValue] = React.useState(0);
  const { current_messages = [] } = useSelector((state) => state.conversation.direct_chat);
  const media = current_messages.filter((item) => item?.type === "msg" && item.subtype === "MEDIA");
  const links = current_messages.filter((item) => item?.type === "msg" && item.subtype === "LINK");
  const documents = current_messages.filter((item) => item?.type === "msg" && item.subtype === "DOCUMENT");

  return (
    <Box
      component="aside"
      aria-label="Shared conversation content"
      sx={rightPanelSx(theme, isDesktop)}
    >
      <Stack height="100%" minHeight={0}>
        <Stack
          direction="row"
          alignItems="center"
          spacing={1.5}
          sx={rightPanelHeaderSx(theme)}
        >
          <IconButton aria-label="Back to contact details" onClick={() => dispatch(UpdateSidebarType("CONTACT"))}>
            <CaretLeft size={21} />
          </IconButton>
          <Stack spacing={0.1}>
            <Typography variant="subtitle1" sx={{ fontWeight: 800 }}>Shared content</Typography>
            <Typography variant="caption" color="text.secondary">Media, links, and documents</Typography>
          </Stack>
        </Stack>

        <Tabs
          value={value}
          onChange={(_, next) => setValue(next)}
          variant="fullWidth"
          sx={{ px: 1.5, minHeight: 54, borderBottom: `1px solid ${alpha(theme.palette.text.primary, 0.08)}`, "& .MuiTab-root": { minHeight: 54, textTransform: "none" } }}
        >
          <Tab label={`Media ${media.length ? `(${media.length})` : ""}`} />
          <Tab label={`Links ${links.length ? `(${links.length})` : ""}`} />
          <Tab label={`Docs ${documents.length ? `(${documents.length})` : ""}`} />
        </Tabs>

        <Stack sx={{ flex: 1, minHeight: 0, overflowY: "auto" }} p={2}>
          {value === 0 && (media.length ? (
            <Box sx={{ display: "grid", gridTemplateColumns: "repeat(2, minmax(0, 1fr))", gap: 1.25 }}>
              {media.map((item) => (
                <Box key={item.id} component="a" href={item.media} target="_blank" rel="noopener noreferrer" sx={{ position: "relative", display: "block", aspectRatio: "1 / 1", overflow: "hidden", borderRadius: "14px", bgcolor: "background.neutral", border: `1px solid ${alpha(theme.palette.text.primary, 0.08)}` }}>
                  {item.mediaType === "image" ? (
                    <Box component="img" src={item.media} alt="Shared media" sx={{ width: "100%", height: "100%", objectFit: "cover", transition: "transform 200ms ease", "&:hover": { transform: "scale(1.04)" } }} />
                  ) : (
                    <Box component="video" src={item.media} sx={{ width: "100%", height: "100%", objectFit: "cover" }} />
                  )}
                </Box>
              ))}
            </Box>
          ) : <EmptyTab icon={<Image size={23} />} title="No shared media" detail="Photos and videos from this conversation will appear here." />)}

          {value === 1 && (links.length ? (
            <Stack spacing={1}>
              {links.map((item) => {
                const url = extractURL(item.message);
                return (
                  <Stack key={item.id} component="a" href={url} target="_blank" rel="noopener noreferrer" direction="row" alignItems="center" spacing={1.25} sx={{ p: 1.5, color: "text.primary", textDecoration: "none", borderRadius: "15px", border: `1px solid ${alpha(theme.palette.text.primary, 0.08)}`, bgcolor: alpha(theme.palette.text.primary, 0.025), "&:hover": { bgcolor: alpha(theme.palette.primary.main, 0.06), borderColor: alpha(theme.palette.primary.main, 0.16) } }}>
                    <Box sx={{ width: 40, height: 40, flexShrink: 0, borderRadius: "12px", display: "grid", placeItems: "center", color: "primary.main", bgcolor: alpha(theme.palette.primary.main, 0.1) }}><LinkSimple size={19} /></Box>
                    <Stack minWidth={0} flex={1}><Typography variant="subtitle2" noWrap>{truncateString(url, 34)}</Typography><Typography variant="caption" color="text.secondary">{convertToIST(item.time)}</Typography></Stack>
                  </Stack>
                );
              })}
            </Stack>
          ) : <EmptyTab icon={<LinkSimple size={23} />} title="No shared links" detail="Links shared in this conversation will appear here." />)}

          {value === 2 && (documents.length ? (
            <Stack spacing={1}>
              {documents.map((item) => (
                <Stack key={item.id} component="button" type="button" onClick={() => window.open(item.media, "_blank")} direction="row" alignItems="center" spacing={1.25} sx={{ p: 1.5, width: "100%", borderRadius: "15px", border: `1px solid ${alpha(theme.palette.text.primary, 0.08)}`, bgcolor: alpha(theme.palette.text.primary, 0.025), color: "text.primary", cursor: "pointer", textAlign: "left", font: "inherit", "&:hover": { bgcolor: alpha(theme.palette.primary.main, 0.06), borderColor: alpha(theme.palette.primary.main, 0.16) } }}>
                  <Box sx={{ width: 40, height: 40, flexShrink: 0, borderRadius: "12px", display: "grid", placeItems: "center", color: "primary.main", bgcolor: alpha(theme.palette.primary.main, 0.1) }}><File size={20} /></Box>
                  <Stack minWidth={0} flex={1}><Typography variant="subtitle2" noWrap>{truncateString(item.mediaType || "Document", 34)}</Typography><Typography variant="caption" color="text.secondary">{convertToIST(item.time)}</Typography></Stack>
                </Stack>
              ))}
            </Stack>
          ) : <EmptyTab icon={<File size={23} />} title="No documents" detail="Files shared in this conversation will appear here." />)}
        </Stack>
      </Stack>
    </Box>
  );
};

export default SharedMessages;
