import React from "react";
import { Box, Stack } from "@mui/material";
import ChatComponent from "./Conversation";
import Chats from "./Chats";
import Contact from "../../sections/main/Contact";
import { useSelector } from "react-redux";
import StarredMessages from "../../sections/main/StarredMessages";
import Media from "../../sections/main/SharedMessages";
import useResponsive from "../../hooks/useResponsive";
import EmptyConversation from "../../components/EmptyConversation";

const GeneralApp = () => {
  const isDesktop = useResponsive("up", "md");
  const { sideBar, room_id, chat_type } = useSelector((state) => state.app);
  const selected = chat_type === "individual" && Boolean(room_id);

  const details = () => {
    switch (sideBar.type) {
      case "CONTACT": return <Contact />;
      case "STARRED": return <StarredMessages />;
      case "SHARED": return <Media />;
      default: return null;
    }
  };

  return (
    <Stack direction="row" sx={{ width: "100%", minWidth: 0, height: "100vh", overflow: "hidden" }}>
      {(isDesktop || !selected) && <Chats />}
      {(isDesktop || selected) && (
        <Box sx={{ height: "100vh", minWidth: 0, flex: 1, bgcolor: "background.default" }}>
          {selected ? <ChatComponent /> : <EmptyConversation />}
        </Box>
      )}
      {sideBar.open && details()}
    </Stack>
  );
};

export default GeneralApp;
